import {STATS,AREAS,RELICS,EVENTS,COMBOS,TRAITS,MISSIONS,CITIES} from './data.js';
import {CARDS,chapter,chapterTarget,level,chainScore,eventFor,setPath,reserveCard,rerollCost,newGame,available,budget,timeBudget,income,forecast,selectCards,move,reroll,resolveYear,chooseEvent,chooseRelic,ending,validateSave} from './engine.js';
import {PATHS,LINKS,CHAPTERS,PROJECTS} from './play-content.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='life-meadow-save-v1',ALBUM='life-meadow-album-v1';let state,tab='board',collection='combos',storageOK=true,album={runs:[],achievements:[]};
try{const raw=localStorage.getItem(KEY);if(raw&&JSON.parse(raw).version===1)localStorage.setItem('life-meadow-v1-backup',raw);state=raw?validateSave(JSON.parse(raw)):newGame();const a=JSON.parse(localStorage.getItem(ALBUM)||'null');if(a&&Array.isArray(a.runs)&&Array.isArray(a.achievements))album=a;}catch{try{const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem('life-meadow-unreadable-backup',raw);}catch{}state=newGame();storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(ALBUM,JSON.stringify(album));}catch{storageOK=false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function act(fn){try{const phase=state.phase,age=state.age;state=fn(state);if(state.phase==='end')recordEnd();save();render();if(phase!==state.phase||age!==state.age){const target=$('.event-card h2,.section-head h2,.ending h2');if(target){target.tabIndex=-1;target.focus();}}}catch(e){toast(e.message);}}
function recordEnd(){const e=ending(state),id=state.seed+'|'+JSON.stringify(state.history.map(h=>[h.cards,h.event]))+'|'+state.relics.join(',');if(!album.runs.some(r=>r.id===id)){album.runs.unshift({id,seed:state.seed,name:state.name,ending:e.name,stats:state.stats,mission:e.mission,mode:state.mode,path:state.path,totalScore:state.totalScore,load:state.load,stars:state.chapterResults.reduce((n,c)=>n+c.stars,0),promises:state.projectResults.filter(p=>p.success).length});album.runs=album.runs.slice(0,30);album.achievements=[...new Set([...album.achievements,...e.achieved])];}}
const effectText=e=>Object.entries(e).map(([k,v])=>`${STATS[k]} ${v>0?'+':''}${v}`).join(' · ');
function top(){return `<header class="topbar"><div class="brand"><div class="brand-mark" aria-hidden="true">❋</div><div><strong>人生原野</strong><small>LIFE MEADOW · 育儿模拟器</small></div></div><div class="top-actions"><span class="chip">V0.3 · PC试玩候选</span><button class="button quiet" data-action="quick-help">怎么玩</button><button class="button quiet" data-action="save-menu">存档</button><button class="button" data-action="new">新的人生 ＋</button></div></header><nav class="tabs" aria-label="游戏视图">${[['board','成长之旅'],['map','机会社区'],['journal','人生年鉴'],['collection','成长图鉴']].map(([id,t])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}" aria-current="${tab===id?'page':'false'}">${t}</button>`).join('')}</nav>`;}
function sidebar(){const f=state.phase==='plan'?forecast(state):null;const trait=TRAITS.find(t=>t.id===state.trait),mission=MISSIONS.find(m=>m.id===state.mission);return `<aside class="side"><section class="panel profile"><div class="profile-top"><span class="profile-name">${esc(state.name)}</span><span class="age-number">${state.age}<small> 岁</small></span></div><div class="trait" title="${esc(trait.text)}">✦ ${trait.name}</div><p class="small">${trait.text}</p>${Object.entries(STATS).map(([k,l])=>`<div class="stat"><div class="stat-label"><span>${l}</span><span>${state.stats[k]}${f&&state.plan.length?`<span class="delta">${f.deltas[k]>=0?'+':''}${f.deltas[k]}</span>`:''}</span></div><div class="bar" role="meter" aria-label="${l}" aria-valuenow="${state.stats[k]}" aria-valuemin="0" aria-valuemax="100"><i style="width:${state.stats[k]}%"></i></div></div>`).join('')}<div class="stress"><div class="stat-label"><span>身心负荷</span><span class="${state.load>55?'bad':''}">${state.load} / 100</span></div><div class="bar"><i style="width:${state.load}%;background:${state.load>55?'#dd9d83':'#83ab97'}"></i></div><p>${state.load>55?'需要多一点恢复和支持。':'还有呼吸和恢复的空间。'}</p></div><p class="small" style="margin-top:15px">${state.mode==='gentle'?'舒缓':'标准'}模式 · 数值为游戏刻度</p></section><section class="panel"><div class="eyebrow">这一局的初心</div><div class="mission-title">${mission.name}</div><p class="small">${mission.text}</p></section><section class="panel"><div class="eyebrow">一路积累的信物 · ${state.relics.length}/5</div><div class="relic-list">${state.relics.length?state.relics.map(id=>{const r=RELICS.find(x=>x.id===id);return `<div class="relic-item" title="${esc(r.text)}"><span class="relic-icon">${r.icon}</span><span>${r.name}</span></div>`;}).join(''):'<p class="small">每走过3年，选择一件信物；类型信物同时增加对应牌的基础星光。</p>'}</div></section></aside>`;}
function timeline(){return `<div class="timeline" aria-label="成长进度">${[0,3,6,9,12,15,18].map((v,i)=>`<div class="timepoint ${state.age>=v?'done':''} ${Math.floor(state.age/3)===i?'current':''}"><b>${v}</b><span>${['初见','幼年','入学','探索','青春','远行','成年'][i]}</span></div>`).join('')}</div>`;}
function world(){const area=AREAS.find(a=>a.id===state.area);return `<div class="world"><img src="placeholder.svg" alt="开源版抽象占位插图" width="1536" height="1024"><div class="world-copy"><div class="eyebrow">CHAPTER ${String(Math.min(6,Math.floor(state.age/3)+1)).padStart(2,'0')} / 06</div><h1>${state.age<3?'每一个小小开始':state.age<6?'世界开始变大':state.age<9?'带着问号长大':state.age<12?'发现自己的光':state.age<15?'练习成为自己':state.age<18?'把选择交还给你':'下一程，由你出发'}</h1><p>${state.age<18?'一年一年，种下更多可能。':'十八年，不过是故事的序章。'}</p><p class="location">⌂ ${state.city} · ${area.name}<br><span class="small">虚构社区剧本</span></p></div></div>`;}
function cardHTML(c){const yes=state.plan.includes(c.id),lv=level(state,c.id);return `<button class="card ${yes?'selected':''}" data-card="${c.id}" aria-pressed="${yes}" title="${esc(c.text)}"><span class="card-tag"><span>${c.tag} · Lv.${lv}</span><span>负荷 ${c.load>0?'+':''}${c.load}</span></span><span class="card-symbol" aria-hidden="true">${c.icon}</span><strong>${c.name}</strong><span class="card-effect"><small>基础成长</small>${Object.entries(c.effect).map(([k,v])=>`${STATS[k]} ${v>0?'+':''}${v+(v>0?lv-1:0)}`).join('<br>')}</span><span class="mastery">${lv===3?'熟练度已满':`再用 ${3-(state.mastery[c.id]||0)%3} 次升级`}${state.carry===c.id?' · 留下的牌':''}</span><span class="card-cost"><span>◷ ${c.time} 时间</span><span>◈ ${c.cost>=0?c.cost:'赚'+(-c.cost)}</span></span>${yes?`<b class="order-badge">${state.plan.indexOf(c.id)+1}</b>`:''}</button>`;}
function chapterPanel(){const c=chapter(state),target=chapterTarget(state),chain=chainScore(state),project=state.project&&PROJECTS.find(p=>p.id===state.project.id);return `<section class="chapter-panel" aria-label="当前篇章挑战"><div class="chapter-heading"><div><div class="eyebrow">三年挑战 · ${Math.floor(state.age/3)*3}—${Math.floor(state.age/3)*3+3}岁</div><h2>${c.name}</h2></div><div class="chapter-score"><b>${state.chapterScore}</b><span> / ${target} ✦</span></div></div><div class="chapter-progress"><i style="width:${Math.min(100,state.chapterScore/target*100)}%"></i>${state.plan.length?`<i class="projected" style="left:${Math.min(100,state.chapterScore/target*100)}%;width:${Math.min(100-Math.min(100,state.chapterScore/target*100),chain.score/target*100)}%"></i>`:''}</div><div class="chapter-meta"><span>还有 ${3-state.age%3} 年 · ${c.rule}</span><span>★ ${target}　★★ ${Math.ceil(target*1.3)}　★★★ ${Math.ceil(target*1.65)}</span></div>${project?`<div class="promise"><div><strong>♡ 约定：${project.name}</strong><span>${project.tags.join(' / ')}牌 · 还剩 ${project.due-state.age+1} 年</span></div><b>${state.project.progress}${state.plan.length?' → '+Math.min(project.need,state.project.progress+state.plan.filter(id=>project.tags.includes(CARDS.find(c=>c.id===id).tag)).length):''} / ${project.need}</b></div>`:`<p class="child-voice">“${c.quote}”</p>`}</section>`;}
function planView(){const b=budget(state),f=forecast(state),chain=chainScore(state),valid=state.plan.length>0&&b.time<=timeBudget(state)&&b.cost<=b.available,path=PATHS.find(p=>p.id===state.path);return `${state.age===0?quickStart():''}${state.migrated?'<div class="hint">旧存档已保留，连锁玩法从当前年份启用，请重新安排本年手牌。开启新局可完整体验三段约定。</div>':''}${chapterPanel()}${state.age===0?`<div class="path-picker" aria-label="开局流派">${PATHS.map(p=>`<button class="path-option ${state.path===p.id?'active':''}" data-path="${p.id}" aria-pressed="${state.path===p.id}"><b>${p.icon} ${p.name}</b><span>${p.from} → ${p.to} · ×${1+.4+.5}</span></button>`).join('')}</div>`:`<div class="build-line">${path.icon} ${path.name} · ${path.from} → ${path.to}，额外 +0.5 倍率</div>`}<div class="section-head"><div><h2>${state.age}—${state.age+1}岁，打出你的连锁</h2><p>选1—3张，按点击顺序出牌。可随时取消或用前后移按钮调整；确认后才结算。</p></div><button class="button" data-action="reroll" ${state.rerolls||state.cash<rerollCost(state)?'disabled':''}>换一手 · ${rerollCost(state)?'◈ 1':'免费'}</button></div><div class="resource-line">可用时间 <b>${timeBudget(state)}</b> · 活动预算 <b>${b.available}</b> 资金 <span>（储蓄 ${state.cash} ＋ 收入 ${b.income} − 房租 ${b.rent}）</span></div><div class="hand" aria-label="本年成长手牌">${available(state).map(cardHTML).join('')}</div><section class="chain-board" aria-label="连锁预览"><div class="chain-top"><span>本年星光</span><div class="formula" aria-live="polite"><b>${chain.base}</b><span>×</span><b>${chain.mult.toFixed(1)}</b>${chain.extra?`<span>${chain.extra>0?'+':''}${chain.extra}</span>`:''}<span>=</span><strong>${chain.score} <small>✦</small></strong></div></div><div class="sequence">${state.plan.length?state.plan.map((id,i)=>{const c=CARDS.find(c=>c.id===id),link=chain.links.find(l=>l.index===i);return `${i?`<span class="link-arrow ${link?'lit':''}" title="${link?.name||'这里还没有连锁'}">${link?'+'+link.bonus.toFixed(1):'→'}</span>`:''}<div class="sequence-card"><span>${i+1}. ${c.icon} ${c.name}</span><div><button data-shift="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="前移${c.name}">←</button><button data-shift="${i}" data-direction="1" ${i===state.plan.length-1?'disabled':''} aria-label="后移${c.name}">→</button><button data-card="${id}" aria-label="移除${c.name}">×</button></div></div>`;}).join(''):'<p class="small">点两张牌试试看：'+path.from+' → '+path.to+'，就能触发你的专属连锁。</p>'}</div><div class="chain-detail">${chain.links.length?chain.links.map(l=>`✦ ${l.name} +${l.bonus.toFixed(1)}`).join('　'):'换个出牌顺序，结果可能就不一样。'}<button class="text-button" data-action="chains">查看6种接法 ↗</button></div></section>${decisionPreview(f,b)}${state.age<17?`<div class="reserve-row"><label for="reserve-card">把一张牌留给明年 <span class="small">· ◈ 2</span></label><select id="reserve-card"><option value="">不留牌，把资金存下</option>${available(state).filter(c=>c.max>state.age).map(c=>`<option value="${c.id}" ${state.reserve===c.id?'selected':''}>${c.name} · ${c.tag}</option>`).join('')}</select></div>`:''}<div class="combo-box"><div class="combo-label">成长回响 · 与星光挑战独立结算</div>${f.combos.map(id=>{const c=COMBOS.find(c=>c.id===id);return `<div class="combo-row lit">${c.name} · ${effectText(c.bonus)}</div>`;}).join('')}<div class="combo-row">负荷 ${state.load} → ${state.load+f.load} · ${state.plan.length?'本年实际变化见上方预览':'留一点空白，也是一种选择'}</div></div><div class="commit-row"><div class="budget"><div>◷ 时间 <strong class="${b.time>timeBudget(state)?'bad':''}">${b.time} / ${timeBudget(state)}</strong>　·　已选 <strong>${state.plan.length} / 3</strong></div><div>◈ 年末结余 <strong class="${b.cost>b.available?'bad':''}">${b.available-b.cost}</strong> <span title="储蓄＋收入−房租−活动−留牌">· ${state.reserve?'含留牌费2':'未留牌，不收费'}</span></div></div><button class="button primary" aria-describedby="plan-status" data-action="resolve" ${!valid?'disabled':''}>确认安排 · ${chain.score} ✦</button></div><p id="plan-status" class="plan-status" role="status">${!state.plan.length?'先选至少1张牌，再确认安排。':b.time>timeBudget(state)?`超出 ${b.time-timeBudget(state)} 点时间：移除一张牌，或换成时间更短的牌。`:b.cost>b.available?`资金还差 ${b.cost-b.available}：取消留牌或选择花费更少的活动。`:'安排可执行。确认后会遇到一个事件，回应后才进入下一年。'}</p><p class="small">星光评价本局的卡牌策略，不评价孩子。达标后仍可冲二星、三星；未达标也能继续。每升一级，卡牌正向基础成长 +1、基础星光 +3。</p>`;}
function lastStrip(){return state.last?`<div class="result-strip">${Object.entries(state.last.deltas).filter(([,v])=>v!==0).map(([k,v])=>`<span class="result-pill">${STATS[k]} ${v>0?'+':''}${v}</span>`).join('')}</div>`:'';}
function eventView(){const e=eventFor(state);return `<div class="section-head"><div><h2>计划之外，也是生活</h2><p>活动已经结算。你的回应，有时会改变未来两年。</p></div></div>${lastStrip()}<div class="score-reveal">本年 +${state.last.score||0} ✦ <span>连锁 ×${(state.last.mult||1).toFixed(1)} · 本章 ${state.chapterScore} / ${chapterTarget(state)}</span></div><article class="event-card"><div class="eyebrow">LIFE HAPPENS · ${state.age}岁</div><h2>${e.title}</h2><p>${e.story}</p><div class="choices">${e.choices.map((c,i)=>`<button class="choice" data-event="${i}" ${state.cash<c.cost?'disabled':''}><strong>${c.label}</strong><span>${c.detail?esc(c.detail)+'<br>':''}${effectText(c.effect)}<br>负荷 ${c.load>0?'+':''}${c.load} · ◈ ${c.cost}${state.cash<c.cost?' · 资金不足':''}</span></button>`).join('')}</div></article>`;}
function chapterResultHTML(c){return c?`<div class="chapter-result"><div class="stars">${'★'.repeat(c.stars)}${'☆'.repeat(3-c.stars)}</div><div><b>${CHAPTERS[c.index].name}</b><p>${c.score} / ${c.target} ✦ · ${c.stars?'挑战达成，奖励 ◈ '+c.reward:'这次没有达标，下一章可以换个思路。'}</p></div></div>`:'';}
function draftView(){return `${chapterResultHTML(state.chapterResults.at(-1))}<div class="section-head"><div><div class="eyebrow">A LITTLE KEEPSAKE</div><h2>${state.age}岁，留住一件成长信物</h2><p>三选一，持续影响这一局余下的人生。</p></div></div><div class="draft-grid">${state.draft.map(id=>{const r=RELICS.find(r=>r.id===id);return `<button class="relic-card" data-relic="${id}"><span class="card-symbol">${r.icon}</span><strong>${r.name}</strong><p>${r.text}${['pages','roots','shoes','blank','bridge','spark'].includes(r.id)?' 对应类型牌基础星光 +3。':r.id==='mix'?' 三种类型再加0.5连锁倍率。':''}</p></button>`;}).join('')}</div><div class="hint">信物会与活动、社区叠加。试着围绕已有组合，发展属于这个家庭的节奏。</div>`;}
function quickStart(expanded=false){return `<details class="quick-start" ${expanded?'open':''}><summary>第一次来？三步走过一年 · 一局18年</summary><ol><li><b>选1—3张牌。</b>卡上是基础成长，实际变化会受已有成长、社区与组合影响；选好后看本年预览。</li><li><b>调整顺序，比较代价。</b>相邻类型符合接法才加星光；成长组合不看顺序。不要只看星光，也看负荷、约定和资金。</li><li><b>确认安排，再回应事件。</b>每3年结算挑战并选信物；18岁看结局。没有达标也能继续，没有唯一正确的人生。</li></ol><p>选牌后下方出现实时预览。留牌花2资金，未打出的牌也能留；每年只留1张。Tab切换控件，Enter或空格操作，Esc关闭弹窗。进度自动存在本机，可从“存档”导出。</p></details>`;}
function decisionPreview(f,b){if(!state.plan.length)return '';return `<section class="decision-preview" aria-label="本年实际变化"><h3>确认前，看这一年的取舍</h3><div class="growth-preview">${Object.entries(STATS).map(([k,v])=>`<div><span>${v}</span><b>${state.stats[k]} → ${state.stats[k]+f.deltas[k]}</b><small class="${f.deltas[k]<0?'bad':''}">${f.deltas[k]>0?'+':''}${f.deltas[k]}</small></div>`).join('')}</div><p><b>负荷 ${state.load} → ${state.load+f.load}</b> · ${state.load+f.load>55?'超过55，本次已计入活力与幸福惩罚。':'超过55会影响活力和幸福；目前未触发。'}</p><p>活动 ${b.cost-b.reserve} ＋ 留牌 ${b.reserve} 资金；结算后余 ${b.available-b.cost}。事件可能继续改变成长与资金。</p>${f.notes.length?`<p class="small">${f.notes.join(' · ')}</p>`:''}</section>`;}
function replayComparison(){const previous=album.runs.find((r,i)=>i>0&&r.seed===state.seed&&r.mode===state.mode&&Number.isFinite(r.totalScore));if(!previous)return '<div class="hint">下局试一个具体目标：比这次多兑现一个约定，或在更低负荷下拿到同样的星光。完成同种子、同难度的第二局后，这里会并列比较。</div>';const delta=state.totalScore-previous.totalScore;return `<section class="replay-review"><h3>同一起点，两条路</h3><p>与本机上一局相同种子、相同难度比较；家庭节奏可以不同。</p><div class="table-wrap"><table><tr><th>结果</th><th>上一局</th><th>这一局</th></tr><tr><td>星光</td><td>${previous.totalScore}</td><td>${state.totalScore}（${delta>=0?'+':''}${delta}）</td></tr><tr><td>兑现约定</td><td>${previous.promises} / 3</td><td>${state.projectResults.filter(p=>p.success).length} / 3</td></tr><tr><td>负荷</td><td>${previous.load}</td><td>${state.load}</td></tr>${Object.entries(STATS).map(([k,v])=>`<tr><td>${v}</td><td>${previous.stats[k]}</td><td>${state.stats[k]}</td></tr>`).join('')}</table></div><p class="small">旧版收藏缺少策略数据时不参与对照。高分不是对人生的评价。</p></section>`;}
function endView(){const e=ending(state);return `<section class="ending"><div class="eyebrow">十八年的回信</div><h2>${e.name}</h2><p>${esc(state.name)}：${e.text}</p><p class="ending-score">总星光 <b>${state.totalScore} ✦</b> · 最强连锁 <b>×${state.bestChain.toFixed(1)}</b> · 兑现约定 <b>${state.projectResults.filter(p=>p.success).length}/3</b></p><div class="chapter-medals">${state.chapterResults.map(c=>`<div title="${CHAPTERS[c.index].name}"><span>第${c.index+1}章</span><b>${'★'.repeat(c.stars)}${'☆'.repeat(3-c.stars)}</b><small>${c.score} ✦</small></div>`).join('')}</div><p class="ending-score">本局初心：<b>${e.mission?'已经达成':'还有另一种可能'}</b> · 发现 ${state.combos.length} 种组合 · 收集 ${state.relics.length} 件信物</p><div class="result-strip">${e.achieved.map(t=>`<span class="result-pill">✧ ${t}</span>`).join('')}</div>${replayComparison()}<div class="modal-actions"><button class="button primary" data-tab="journal">翻开人生年鉴</button><button class="button" data-action="replay">相同起点，再试一种选择</button><button class="button" data-action="share">复制这段人生</button></div><p class="small">一局已经完整结束。相同种子可重试其他出牌顺序、约定或家庭节奏；完成记录保存在本机。</p></section>`;}
function board(){return world()+timeline()+(state.phase==='plan'?planView():state.phase==='event'?eventView():state.phase==='draft'?draftView():endView());}
function mapView(){return `<div class="section-head"><div><div class="eyebrow">OPPORTUNITY NEIGHBORHOODS</div><h2>${state.city} · 选择生活的土壤</h2><p>社区有长处，也有代价。搬家花费3资金，每年最多一次。</p></div></div><div class="hint">以下为虚构社区和0—100游戏指数，六座城市共用平衡参数。居民收入、住房拥有率和教育指数只提供背景，不直接决定孩子的成长。</div><div class="area-grid">${AREAS.map(a=>`<article class="area-card ${state.area===a.id?'current':''}"><div class="area-heading"><div><h3>${a.name}</h3><div class="small">${a.type}${state.area===a.id?' · 现在的家':''}</div></div><span class="area-icon">${a.icon}</span></div><p class="small">${a.desc}</p><div class="area-metrics">${[['教育指数',a.education],['收入指数',a.income],['住房拥有指数',a.ownership],['绿地指数',a.green],['邻里支持',a.support],['服务可达性',a.care]].map(([k,v])=>`<div>${k}<b>${v}</b></div>`).join('')}</div><div class="small">每年房租 ◈ ${a.rent} · 通勤占用 ◷ ${a.commute}<br>每年基础加成：${effectText(a.bonus)}</div><button class="button ${state.area===a.id?'':'primary'}" data-move="${a.id}" ${state.phase!=='plan'||state.area===a.id||state.moved||state.cash<3?'disabled':''}>${state.area===a.id?'住在这里':state.moved?'本年已经搬过家':'搬到这里 · ◈ 3'}</button></article>`).join('')}</div><p class="small">早搬与晚搬会产生不同的累计环境收益，但这些差异是游戏规则，不能作为真实购房或教育建议。</p>`;}
const colors=['#ecc56b','#9acaad','#d8a78e','#adbfea','#d0b6df'];
function chart(){if(!state.history.length)return '';const records=[newGame({seed:state.seed}).stats,...state.history.map(h=>h.after)];return `<svg class="chart" viewBox="0 0 700 230" role="img" aria-label="成长属性随年龄变化的折线图"><g stroke="#365448" stroke-width="1">${[0,25,50,75,100].map(v=>`<line x1="42" y1="${198-v*1.6}" x2="675" y2="${198-v*1.6}"/><text x="8" y="${203-v*1.6}" fill="#b6c7b8" stroke="none" font-size="12">${v}</text>`).join('')}</g>${Object.keys(STATS).map((k,i)=>`<polyline points="${records.map((r,j)=>`${42+j*633/18},${198-r[k]*1.6}`).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="2.5"/>`).join('')}<text x="42" y="221" fill="#b6c7b8" font-size="12">0岁</text><text x="650" y="221" fill="#b6c7b8" font-size="12">18岁</text></svg><div class="legend">${Object.values(STATS).map((v,i)=>`<span style="color:${colors[i]}">━ ${v}</span>`).join('')}</div>`;}
function journal(){return `<div class="section-head"><div><div class="eyebrow">THE YEARS WE GREW</div><h2>${esc(state.name)}的人生年鉴</h2><p>记下结果，也记下结果是怎样发生的。</p></div><button class="button" data-action="export">导出存档</button></div>${chart()}${state.history.length?`<div style="margin-top:28px">${[...state.history].reverse().map(h=>{const e=EVENTS.find(e=>e.id===h.event.id);return `<article class="log"><h3>${h.age}—${h.age+1}岁 · ${AREAS.find(a=>a.id===h.area).name}</h3><p>${h.cards.map(id=>CARDS.find(c=>c.id===id).name).join(' ＋ ')}</p><p>意外：${esc(h.event.title||e?.title)} → ${esc(h.event.label||e?.choices[h.event.choice].label)}${h.score!==undefined?` · ${h.score} ✦ ×${h.mult}`:''}</p>${h.notes.map(n=>`<p style="color:var(--gold)">✦ ${esc(n)}</p>`).join('')}<p>${Object.entries(STATS).map(([k,v])=>`${v} ${h.after[k]}`).join(' · ')}</p></article>`;}).join('')}</div>`:'<div class="empty"><div class="card-symbol">≋</div>第一年的回忆，正在等待发生。</div>'}`;}
function collectionView(){return `<div class="section-head"><div><div class="eyebrow">A CABINET OF POSSIBILITIES</div><h2>发现更多成长的方式</h2><p>收集的是故事和策略，不是更优越的孩子。</p></div></div><div class="subnav">${[['combos','组合回响 · 5'],['relics','成长信物 · 12'],['cards','活动卡牌 · 30'],['album','人生收藏 · '+album.runs.length]].map(([id,t])=>`<button class="button ${collection===id?'primary':''}" data-collection="${id}">${t}</button>`).join('')}</div>${collection==='combos'?`<div class="collection-grid">${COMBOS.map(c=>`<article class="collection-item"><div class="card-symbol">${state.combos.includes(c.id)?'✦':'✧'}</div><h3>${c.name}</h3><p>${c.text}</p><p>${effectText(c.bonus)}</p><p>${state.combos.includes(c.id)?'本局已发现':'等待这一局相遇'}</p></article>`).join('')}</div>`:collection==='relics'?`<div class="collection-grid">${RELICS.map(c=>`<article class="collection-item"><div class="card-symbol">${c.icon}</div><h3>${c.name}</h3><p>${c.text}</p><p>${state.relics.includes(c.id)?'本局已拥有':'每3年有机会选择'}</p></article>`).join('')}</div>`:collection==='cards'?`<div class="collection-grid">${CARDS.map(c=>`<article class="collection-item"><div class="card-symbol">${c.icon}</div><h3>${c.name}</h3><p>${c.tag} · ${c.min}—${c.max}岁 · ◷${c.time} · ◈${c.cost}</p><p>${effectText(c.effect)} · 负荷${c.load>0?'+':''}${c.load}</p><p>${c.text}</p>${PROJECTS.some(p=>p.unlock===c.id)?`<p>${state.unlocked.includes(c.id)?'✦ 本局已解锁':'♡ 通过约定解锁'}</p>`:''}</article>`).join('')}</div>`:`${album.achievements.length?`<div class="result-strip">${album.achievements.map(a=>`<span class="result-pill">✧ ${esc(a)}</span>`).join('')}</div>`:''}${album.runs.length?`<div class="collection-grid">${album.runs.map(r=>`<article class="collection-item"><div class="card-symbol">❋</div><h3>${esc(r.name)} · ${esc(r.ending)}</h3><p>种子：${esc(r.seed)}</p><p>${r.mission?'守住初心':'一条不同的路'}</p></article>`).join('')}</div>`:'<div class="empty">完成一局后，结局和成就会留在这里。<br>收藏不会带来数值优势；每个人都能从同样的起点出发。</div>'}`}`;}
function render(){const handScroll=$('.hand')?.scrollLeft||0;const active=document.activeElement,oldFocus=active?.dataset,focusCard=oldFocus?.card;const focusAttrs=['action','path','shift','direction','tab','collection'];const focusSelector=active?.id?'#'+CSS.escape(active.id):focusAttrs.filter(k=>oldFocus?.[k]!==undefined).map(k=>'[data-'+k+'="'+CSS.escape(oldFocus[k])+'"]').join('');$('#app').innerHTML=`<div class="shell">${top()}<div class="layout"><main class="main" id="main-content">${tab==='board'?board():tab==='map'?mapView():tab==='journal'?journal():collectionView()}</main>${sidebar()}</div><footer class="foot"><span>人生原野 · 独立试玩版　|　${storageOK?'进度自动保存在当前设备':'自动保存不可用，请导出存档'}　|　种子 ${esc(state.seed)}</span><div class="inline"><button data-action="help">玩法与科学边界</button><button data-action="future">完整版计划</button></div></footer></div>`;if($('.hand'))$('.hand').scrollLeft=handScroll;if(focusCard)$(`.hand [data-card="${focusCard}"]`)?.focus({preventScroll:true});else if(focusSelector)$(focusSelector)?.focus({preventScroll:true});}
function modal(title,content){$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" data-action="close" aria-label="关闭对话框">×</button></div>${content}`;$('#modal').showModal();}
function newDialog(replay=false){modal(replay?'相同起点，新的选择':'开启一段新的人生',`<p>${state.age>0&&state.phase!=='end'?'开始新局将替换当前自动存档；可以先在“存档”里导出。':'一局18个年份。每年选牌、回应意外，每3年获得一件信物。'}</p><form id="new-form"><label class="field">孩子的名字<input name="child" value="${esc(state.name)}" maxlength="12" required></label><div class="fields"><label class="field">故事发生在<select name="city">${CITIES.map(c=>`<option ${c===state.city?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">节奏<select name="mode"><option value="standard" ${state.mode==='standard'?'selected':''}>标准 · 需要权衡预算</option><option value="gentle" ${state.mode==='gentle'?'selected':''}>舒缓 · 更宽裕的预算</option></select></label></div><label class="field">家庭节奏<select name="path">${PATHS.map(p=>`<option value="${p.id}" ${state.path===p.id?'selected':''}>${p.name} · ${p.from} → ${p.to}</option>`).join('')}</select></label><label class="field">人生种子<input name="seed" value="${esc(replay?state.seed:'LIFE-'+Math.random().toString(36).slice(2,8).toUpperCase())}" maxlength="40" required></label><p class="small">相同种子、家庭节奏和操作会得到相同结果。流派、留牌和约定选择会改变接下来的手牌。城市名称提供故事背景，当前共用虚构规则。</p><div class="modal-actions"><button class="button primary" type="submit">开始这段人生</button><button class="button" type="button" data-action="daily">使用今日共同种子</button></div></form>`);}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='life-meadow-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('存档已导出，包含当前人生进度。');}
function help(){modal('怎么玩，以及它能解释什么',`<h3>连锁、篇章和约定</h3><p>按顺序选牌，匹配的相邻类型各加0.4倍率；家庭节奏再加0.5。基础星光为每张4＋时间×2，篇章偏好牌再加6（前四章）。累计3次使用升一级，最多Lv.3。</p><p>每三年结算一次挑战，达到目标的1、1.3、1.65倍可得一、二、三星，每星奖励2资金。0、6、12岁接到两年约定；打出对应类型来推进，兑现后选择解锁专属牌或领取6资金。花2资金可保留手牌到明年；每年换牌一次。</p><h3>三个步骤，走过一年</h3><ol><li>从5张手牌中选1—3张；注意时间和预算。</li><li>不同类型形成组合。确认后结算，再回应一个随机事件。</li><li>每3年选择一件持续生效的信物，18岁得到结局与复盘。</li></ol><h3>数学让选择有代价</h3><p>正向基础收益 ×（1 − 当前属性 ÷ 150），再扣1点年度维持消耗，四舍五入。社区、气质、组合和信物先加入基础收益。负荷超过55时会扣减活力和幸福。事件收益直接结算。留白能恢复，搬家有成本。</p><h3>生物学有启发，不等于医学模型</h3><p>气质、压力积累、恢复和环境共同作用，是本作的灵感。气质标签不等于基因检测结果。所有系数、健康事件频率和成长分数均为游戏设定。</p><p>精神分裂症涉及多个基因及环境因素，不能由单个基因或几次养育选择预测。游戏只设置青少年求助故事，不诊断、不显示编造的个人患病概率，也不把疾病当作失败结局。<a href="https://www.nimh.nih.gov/health/publications/schizophrenia" target="_blank" rel="noopener">NIMH 科普</a></p><h3>经济学的边界</h3><p>邻里研究启发“累计环境暴露”的玩法，但美国研究不能直接转换成中国社区的个人收益预测。这里的社区、收入、住房和教育指数全部虚构；背景指数不直接给孩子加分。<a href="https://www.nber.org/papers/w21156" target="_blank" rel="noopener">Moving to Opportunity 研究</a></p><h3>随时暂停</h3><p>进度仅自动保存在当前浏览器，没有账号同步。可导出、导入存档。无连续签到奖励、付费抽卡或真实交易。读取存档时会校验格式，但本地分数不适合竞技排行榜。</p>`);}
function future(){modal('试玩候选与后续方向',`<p>当前试玩的18年、30张活动牌、12件信物和所有结局均免费开放。当前为PC浏览器试玩候选，尚未开放收费。</p><h3>完整版的设计方向</h3><div class="table-wrap"><table><tr><th>想获得什么</th><th>值得付费的内容</th></tr><tr><td>新的故事与情感</td><td>不同家庭关系、时代背景和成人阶段</td></tr><tr><td>更多策略深度</td><td>有独特机制的新社区、职业与信物</td></tr><tr><td>创造与表达</td><td>剧本编辑器、挑战分享、可收藏的人生册</td></tr></table></div><p>计划采用一次购买完整内容、按需购买扩展剧本。价格和内容尚待真实试玩反馈验证，不出售“更好的基因”、疾病豁免或抽卡机会。</p><p class="small">Steam版与微信小游戏版尚未上架。当前为网页试玩，可在手机与电脑继续同一种玩法。</p>`);}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if(d.tab){tab=d.tab;render();return;}if(d.card){act(s=>selectCards(s,s.plan.includes(d.card)?s.plan.filter(id=>id!==d.card):[...s.plan,d.card]));return;}if(d.path){act(s=>setPath(s,d.path));return;}if(d.shift!==undefined){act(s=>{const ids=[...s.plan],a=Number(d.shift),b=a+Number(d.direction);[ids[a],ids[b]]=[ids[b],ids[a]];return selectCards(s,ids);});return;}if(d.event!==undefined){act(s=>chooseEvent(s,Number(d.event)));return;}if(d.relic){act(s=>chooseRelic(s,d.relic));return;}if(d.move){act(s=>move(s,d.move));return;}if(d.collection){collection=d.collection;render();return;}switch(d.action){case'quick-help':modal('一局怎样玩',quickStart(true));break;case'chains':modal('连锁接法 · 顺序很重要',`<p>相邻两张类型符合下列接法，就加0.4倍率。匹配本局家庭节奏，再加0.5。</p><div class="collection-grid">${LINKS.map(l=>`<div class="collection-item"><h3>${l.from} → ${l.to}</h3><p>${l.name}</p></div>`).join('')}</div><p>例如：探索 → 创造 → 社交，在好奇工坊下是 ×2.3。反过来出同样三张牌，结果会不同。</p>`);break;case'resolve':act(resolveYear);break;case'reroll':act(reroll);break;case'new':newDialog();break;case'replay':newDialog(true);break;case'close':$('#modal').close();break;case'help':help();break;case'future':future();break;case'daily':$('#new-form [name=seed]').value='DAY-'+new Date().toISOString().slice(0,10);toast('已填入今日种子，无限次游玩，没有限时奖励。');break;case'save-menu':modal('把这一段人生带走',`<p>当前进度自动保存在这台设备。换浏览器或清除网站数据可能丢失进度，可导出一份备份。</p><p class="small">${esc(state.name)} · ${state.age}岁 · 种子 ${esc(state.seed)}</p><div class="modal-actions"><button class="button primary" data-action="export">导出当前存档</button><button class="button" data-action="import">导入存档并替换当前进度</button></div>`);break;case'export':exportSave();break;case'import':$('#import-file').click();break;case'share':{const end=ending(state),text=`我在《人生原野》陪${state.name}走过了18年，结局是「${end.name}」。发现${state.combos.length}种成长组合。人生种子：${state.seed}。同样的起点，你会怎么选？`;try{await navigator.clipboard.writeText(text);toast('人生摘要已复制。');}catch{modal('分享这段人生',`<p>${esc(text)}</p><p class="small">长按文字即可复制。</p>`);}break;}}});
document.addEventListener('change',e=>{if(e.target.id==='reserve-card')act(s=>reserveCard(s,e.target.value||null));});
document.addEventListener('submit',e=>{if(e.target.id!=='new-form')return;e.preventDefault();const f=new FormData(e.target);state=newGame({name:f.get('child'),city:f.get('city'),seed:f.get('seed'),mode:f.get('mode'),path:f.get('path')});tab='board';save();$('#modal').close();render();toast('新的人生已经开始。');});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('存档文件过大。');const imported=validateSave(JSON.parse(await f.text()));state=imported;tab='board';save();$('#modal').close();render();toast('已恢复存档。');}catch(err){toast('无法导入：'+err.message);}e.target.value='';});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
save();render();
// Optional WebMCP: the same read-only state and staged actions as the visible UI.
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_parenting_game',description:'Read the current fictional parenting game state and available cards without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({age:state.age,phase:state.phase,stats:state.stats,cash:state.cash,load:state.load,path:state.path,chapter:chapter(state).name,chapterScore:state.chapterScore,target:chapterTarget(state),project:state.project,chain:chainScore(state),cards:available(state).map(c=>({id:c.id,name:c.name})),selected:state.plan})});register({name:'stage_growth_cards',description:'Select up to three available activity cards. Does not advance the year.',inputSchema:{type:'object',properties:{cardIds:{type:'array',items:{type:'string'},maxItems:3}},required:['cardIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Array.isArray(input.cardIds)||Object.keys(input).some(k=>k!=='cardIds'))throw Error('Expected cardIds only.');state=selectCards(state,input.cardIds);tab='board';save();render();return {selected:state.plan,preview:forecast(state)};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
